<?php require_once 'includes/db.php';require_once 'includes/functions.php';if(empty($_SESSION['cart'])){header('Location: cart.php');exit;}$items=[];$total=0;foreach($_SESSION['cart'] as $id=>$qty){$id=(int)$id;$s=$conn->prepare("SELECT * FROM products WHERE id=? AND active=1");$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();if($p&&(int)$p['stock']>0){$p['qty']=min((int)$qty,(int)$p['stock']);$total+=$p['qty']*$p['price'];$items[]=$p;}}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(mb_strlen($name)<2)$errors[]='Enter your full name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!preg_match('/^[0-9+() -]{7,20}$/',$phone))$errors[]='Enter a valid phone number.';if(mb_strlen($address)<8)$errors[]='Enter a complete address.';if(!$errors){try{$conn->begin_transaction();$s=$conn->prepare("INSERT INTO orders(customer_name,email,phone,address,total,status) VALUES(?,?,?,?,?,'Placed')");$s->bind_param('ssssd',$name,$email,$phone,$address,$total);$s->execute();$oid=$conn->insert_id;foreach($items as $p){$lock=$conn->prepare("SELECT stock FROM products WHERE id=? FOR UPDATE");$lock->bind_param('i',$p['id']);$lock->execute();$stock=$lock->get_result()->fetch_assoc();if(!$stock||(int)$stock['stock']<$p['qty'])throw new Exception('Stock changed. Please update your cart.');$up=$conn->prepare("UPDATE products SET stock=stock-? WHERE id=?");$up->bind_param('ii',$p['qty'],$p['id']);$up->execute();$line=$conn->prepare("INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)");$line->bind_param('isiid',$oid,$p['id'],$p['name'],$p['qty'],$p['price']);$line->execute();}$conn->commit();$_SESSION['cart']=[];$_SESSION['order_id']=$oid;header('Location: success.php');exit;}catch(Throwable $ex){$conn->rollback();$errors[]=$ex->getMessage();}}}$title='Checkout';include 'includes/header.php';?>
<section><div class="heading"><div><small>ALMOST YOURS</small><h2>Checkout</h2></div></div><div class="cart-layout"><form class="form" method="post"><h3>Delivery details</h3><?php foreach($errors as $err):?><div class="flash"><?=e($err)?></div><?php endforeach;?><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Full name<input name="name" minlength="2" required value="<?=e($_POST['name']??'')?>"></label><label>Email<input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></label><label>Phone<input name="phone" required pattern="[0-9+() -]{7,20}" value="<?=e($_POST['phone']??'')?>"></label><label>Delivery address<textarea name="address" minlength="8" required rows="4"><?=e($_POST['address']??'')?></textarea></label><button class="btn dark full">Place demo order · ₹<?=number_format($total,2)?></button><small>Demo checkout only. Do not enter payment details.</small></form><aside class="summary"><h3>Your order</h3><?php foreach($items as $p):?><p><?=e($p['name'])?> × <?=$p['qty']?> <b>₹<?=number_format($p['qty']*$p['price'],2)?></b></p><?php endforeach;?><hr><p>Total <b>₹<?=number_format($total,2)?></b></p></aside></div></section><?php include 'includes/footer.php';?>